import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  mix,
  smoothstep,
  sin,
  fract,
  dot,
  length,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, ClampToEdgeWrapping } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const inkC = new Color(colors.ink);
  const surfaceC = new Color(colors.surface);
  const accentC = new Color(colors.accent);

  const root = new Group();
  root.name = 'home-hero-showpiece';

  const timelines = [];
  const disposables = [];

  // ---------------------------------------------------------------------
  // STAGE — engineered gradient backdrop (avoids FLAT_VOID)
  // ---------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ side: DoubleSide });

  const uvNode = uv();
  const gradientFactor = smoothstep(0.0, 1.0, uvNode.y);
  const baseColor = mix(
    vec3(inkC.r, inkC.g, inkC.b),
    vec3(surfaceC.r, surfaceC.g, surfaceC.b),
    gradientFactor
  );

  const centered = uvNode.sub(vec2(0.5, 0.55));
  const dist = length(centered);
  const glow = smoothstep(0.55, 0.0, dist).mul(0.12);
  const colorWithGlow = mix(baseColor, vec3(accentC.r, accentC.g, accentC.b), glow);

  const grainNoise = fract(
    sin(dot(uvNode.mul(4331.0), vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grainAmt = grainNoise.sub(0.5).mul(0.035);
  backdropMat.colorNode = colorWithGlow.add(grainAmt);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0.1, -1.9);
  root.add(backdrop);
  disposables.push(() => {
    backdropGeo.dispose();
    backdropMat.dispose();
  });

  // ---------------------------------------------------------------------
  // Depth plane 2 — soft accent halo behind the hero image
  // ---------------------------------------------------------------------
  const glowGeo = new PlaneGeometry(3.6, 3.6);
  const glowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  });
  const glowUv = uv();
  const glowDist = length(glowUv.sub(vec2(0.5, 0.5)));
  const glowAlpha = smoothstep(0.5, 0.0, glowDist).mul(0.22);
  glowMat.colorNode = vec3(accentC.r, accentC.g, accentC.b);
  glowMat.opacityNode = glowAlpha;
  const glowHalo = new Mesh(glowGeo, glowMat);
  glowHalo.position.set(0, 0, -0.32);
  root.add(glowHalo);
  disposables.push(() => {
    glowGeo.dispose();
    glowMat.dispose();
  });

  // ---------------------------------------------------------------------
  // Subject — the floating accent image (sprite, billboards to camera)
  // ---------------------------------------------------------------------
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const heroHeight = 3.0;
  const heroWidth = heroHeight * aspect;

  const heroGeo = new PlaneGeometry(heroWidth, heroHeight);
  const heroMat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });
  heroMat.opacity = 0;

  const heroPlane = new Mesh(heroGeo, heroMat);
  heroPlane.position.set(0, 0, 0);
  root.add(heroPlane);
  disposables.push(() => {
    heroGeo.dispose();
    heroMat.dispose();
  });

  let heroTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      heroTexture = tex;
      tex.wrapS = ClampToEdgeWrapping;
      tex.wrapT = ClampToEdgeWrapping;
      // Atlas region mapping (offset/repeat) if the source texture is larger
      // than the region we need — safe default is full coverage.
      const texW = tex.image?.width || rectW;
      const texH = tex.image?.height || rectH;
      const offsetX = 0 / texW;
      const offsetY = 1 - (0 + rectH) / texH;
      const repeatX = rectW / texW;
      const repeatY = rectH / texH;
      tex.offset.set(offsetX, offsetY);
      tex.repeat.set(repeatX, repeatY);
      tex.needsUpdate = true;

      heroMat.map = tex;
      heroMat.needsUpdate = true;
    }).catch(() => {});
  }

  // Billboard toward camera every frame (sprite render mode).
  const billboardHandler = (renderer, scene, camera) => {
    heroPlane.quaternion.copy(camera.quaternion);
    glowHalo.quaternion.copy(camera.quaternion);
  };
  heroPlane.onBeforeRender = billboardHandler;
  glowHalo.onBeforeRender = billboardHandler;

  // ---------------------------------------------------------------------
  // Node-local rim/accent light (scene only provides ambient + key)
  // ---------------------------------------------------------------------
  const rimLight = new THREE.DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-1.8, 1.2, 1.6);
  root.add(rimLight);
  disposables.push(() => {
    root.remove(rimLight);
    rimLight.dispose?.();
  });

  // ---------------------------------------------------------------------
  // MOTION — weighted entrance + idle breathing (single slow transform)
  // ---------------------------------------------------------------------
  root.position.y -= 0.3;
  root.scale.setScalar(0.98);

  const entrance = gsap.timeline();
  entrance.to(root.position, {
    y: root.position.y + 0.3,
    duration: 0.7,
    ease: 'power3.out',
  });
  entrance.to(
    heroMat,
    {
      opacity: 1,
      duration: 0.6,
      ease: 'power2.out',
    },
    0.05
  );
  entrance.to(
    root.scale,
    {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.5,
      ease: 'power2.out',
    },
    0.1
  );
  entrance.to(
    root.scale,
    {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.9,
      ease: 'power4.out',
    },
    0.55
  );
  timelines.push(entrance);

  const idleBreath = gsap.timeline({ delay: 1.5, repeat: -1, yoyo: true });
  idleBreath.to(heroPlane.scale, {
    x: 1.02,
    y: 1.02,
    duration: 3.2,
    ease: 'sine.inOut',
  });
  timelines.push(idleBreath);

  // ---------------------------------------------------------------------
  // Cinematic primitives — none specified for this element.
  // ---------------------------------------------------------------------
  const primitiveResults = [];

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const tl of timelines) {
      tl.kill();
    }
    for (const p of primitiveResults) {
      p?.cleanup?.();
    }
    heroPlane.onBeforeRender = null;
    glowHalo.onBeforeRender = null;
    for (const dispose of disposables) {
      try {
        dispose();
      } catch (e) {
        // no-op
      }
    }
    if (heroTexture) {
      heroTexture.dispose();
    }
  };

  return root;
}
